style.css:
body::before {
    content: '';
    background-image: url('https://path_to_your_cat_image.gif'); /* ใส่ URL ของรูปแมวที่ต้องการ */
    position: fixed;
    width: 100px;
    height: 100px;
    top: 0;
    right: 0;
    z-index: 1000;
    animation: move-cat 3s infinite alternate; /* เพิ่ม animation */
}

@keyframes move-cat {
    0% {
        transform: translateX(0); /* เริ่มจากตำแหน่งเดิม */
    }
    100% {
        transform: translateX(-200px); /* ย้ายไปทางซ้าย 200px */
    }
}
